package com.tripmateai.service;
import com.tripmateai.ai.AiProviderClient; import com.tripmateai.dto.request.packing.GeneratePackingRequest; import com.tripmateai.dto.response.packing.AiPackingItemResponse; import com.tripmateai.entity.*; import com.tripmateai.exception.BadRequestException; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.impl.PackingServiceImpl; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class PackingServiceImplTest { @Mock TripRepository trips; @Mock PackingChecklistRepository checklists; @Mock PackingItemRepository items; @Mock AiProviderClient ai; @InjectMocks PackingServiceImpl service; Trip trip; PackingChecklist checklist; @BeforeEach void setup(){MockitoAnnotations.openMocks(this);var u=new User();u.setId(1L);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new UserPrincipal(u),null,List.of()));var d=new Destination();d.setCity("Goa");d.setCountry("India");trip=new Trip();trip.setId(2L);trip.setUser(u);trip.setDestination(d);trip.setTripName("Goa");trip.setStartDate(LocalDate.now().plusDays(1));trip.setEndDate(LocalDate.now().plusDays(3));checklist=new PackingChecklist();checklist.setId(3L);checklist.setTrip(trip);checklist.setUser(u);when(trips.findByIdAndUser(2L,u)).thenReturn(Optional.of(trip));when(checklists.findByTripAndUser(trip,u)).thenReturn(Optional.of(checklist));when(items.findByChecklist(checklist)).thenReturn(List.of());} @AfterEach void clear(){SecurityContextHolder.clearContext();} @Test void savesValidAiSuggestion(){var x=new AiPackingItemResponse("T-shirt","CLOTHING",3);when(ai.generatePacking(trip,null)).thenReturn(List.of(x));when(items.findByChecklistAndNameIgnoreCase(checklist,"T-shirt")).thenReturn(Optional.empty());service.generate(2L,new GeneratePackingRequest(null));verify(items).save(argThat(i->i.getName().equals("T-shirt")&&i.getQuantity()==3));} @Test void skipsDuplicateAiSuggestion(){var x=new AiPackingItemResponse("T-shirt","CLOTHING",3);when(ai.generatePacking(trip,null)).thenReturn(List.of(x));when(items.findByChecklistAndNameIgnoreCase(checklist,"T-shirt")).thenReturn(Optional.of(new PackingItem()));service.generate(2L,new GeneratePackingRequest(null));verify(items,never()).save(any());} @Test void rejectsInvalidAiItem(){when(ai.generatePacking(trip,null)).thenReturn(List.of(new AiPackingItemResponse("", "CLOTHING", 0)));assertThrows(BadRequestException.class,()->service.generate(2L,new GeneratePackingRequest(null)));} @Test void propagatesProviderFailure(){when(ai.generatePacking(trip,null)).thenThrow(new BadRequestException("AI provider request failed"));assertThrows(BadRequestException.class,()->service.generate(2L,new GeneratePackingRequest(null)));}}
